from RPLCD.i2c import CharLCD

# Display driver for Raspberry Pi
class DisplayDriver:
    """Driver for the PCF8574-based character LCD display."""

    def __init__(self, i2c_bus_number, device_address):
        """Initialize the display driver."""
        try:
            self.lcd = CharLCD('PCF8574', device_address, custom_chars=None,
                               num_backlight_bits=8, is_red_board=False)
        except Exception as e:
            self.lcd = None
            print(f"Error initializing display: {e}")

    def write_message(self, message_text):
        """Write a message to the display."""
        if self.lcd is None:
            return
        try:
            self.lcd.clear()
            self.lcd.write_string(message_text)
        except Exception as e:
            print(f"Error writing to display: {e}")

    def close(self):
        """Release the display resources."""
        if self.lcd is not None:
            try:
                self.lcd.clear()
                self.lcd.close()
            except Exception as e:
                print(f"Error closing display: {e}")
            finally:
                self.lcd = None


def run_display_loop(display_driver, message_list):
    """Run the display loop, showing each message in turn."""
    try:
        for message in message_list:
            display_driver.write_message(message)
