import serial
import time

# --- Configuration ---
SERIAL_PORT = '/dev/ttyUSB0'  # The serial port the device is connected to.
BAUD_RATE = 9600             # How fast the Raspberry Pi talks to the device.
TIMEOUT = 1                  # How long to wait for a response (in seconds).

# --- Functions ---
def open_serial_port(port, baudrate, timeout):
    """Opens the serial port and returns a Serial object."""
    try:
        # Open the serial port.  'serial' is a library for talking over serial.
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_data(serial_port):
    """Reads one line of data from the serial port."""
    try:
        # Read a line of data from the serial port.  .decode('ascii', errors='replace')
        # translates the raw bytes into text, replacing any bad characters.
        return serial_port.readline().decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def is_valid_data(data):
    """Checks if the data is not empty."""
    return data is not None and data != ""

def print_data(data):
    """Prints the data to the screen."""
    if data:
        print(f"Received: {data}")

def main():
    """Main program loop."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Could not open serial port.  Exiting.")
        return

    try:
        # Loop forever, reading and printing data.
        while True:
            data = read_data(serial_connection)
            if is_valid_data(data):
                print_data(data)
            time.sleep(1)  # Wait one second before reading again.

    except KeyboardInterrupt:
        # If the user presses Ctrl+C, exit cleanly.
        print("\nExiting program.")

    finally:
        # Always close the serial port when we're done.
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

# --- Run the program ---
if __name__ == "__main__":
    main()

