logger = logging.getLogger(__name__)

# Serial port configuration
SERIAL_PORT = '/dev/serial0'  # Raspberry Pi's UART port
BAUD_RATE = 9600             # Communication speed
TIMEOUT = 1                  # Timeout for reads

def configure_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        serial_port = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        return serial_port
    except serial.SerialException as e:
        logger.error(f"Could not open serial port {port}: {e}")
        sys.exit(1)

def read_serial_data(serial_port):
    """Reads a line of data from the serial port."""
    try:
        data = serial_port.readline().decode('utf-8').strip()
        return data
    except serial.SerialException as e:
        logger.error(f"Serial read error: {e}")
        return None

def process_reading(reading):
    """Processes a reading and returns its value if valid."""
    if reading:
        try:
            value = float(reading)
            return value
        except ValueError:
            logger.warning(f"Invalid reading format: {reading}")
            return None
    return None

def main():
    """Main function to exchange data with the UART device."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    try:
        while True:
            serial_data = read_serial_data(serial_connection)
            if serial_data:
                processed_value = process_reading(serial_data)
                if processed_value is not None:
                    logger.info(f"Received value: {processed_value}")
            time.sleep(0.1)  # Reduced sleep time for responsiveness
    except KeyboardInterrupt:
        logger.info("Exiting program.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logger.info("Serial port closed.")

