def configure_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error configuring serial port: {e}")
        return None

def read_serial_data(serial_port):
    """Reads a line of data from the serial port, if available."""
    try:
        if serial_port and serial_port.in_waiting > 0:
            return serial_port.readline().decode('ascii', errors='replace').strip()
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def process_data(data):
    """Processes the received data (in this case, just prints it)."""
    if data:
        print(f"Received: {data}")

def send_data(serial_port, data):
    """Sends data over the serial port."""
    try:
        if serial_port:
            serial_port.write(data.encode('ascii'))
    except serial.SerialException as e:
        print(f"Error writing to serial port: {e}")

def main_loop(serial_port):
    """Main loop to read, process, and send data."""
    while True:
        data = read_serial_data(serial_port)
        process_data(data)
        time.sleep(0.1)

def cleanup_serial(serial_port):
    """Closes the serial port."""
    if serial_port and serial_port.is_open:
        serial_port.close()
        print("Serial port closed.")

def main():
